def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_def_ever = any(a == 'D' for a in op)
    opp_coop_rate = sum(1 for a in op if a == 'C') / n

    apologize = False
    if n >= 1 and my[-1] == 'D' and op[-1] == 'C':
        apologize = True
    if n >= 2 and my[-2] == 'D' and op[-2] == 'C':
        apologize = True

    if not opp_def_ever:
        if n >= 98:
            return 'D'
        if apologize:
            return 'C'
        if n >= 10 and n % 5 == 0:
            return 'D'
        return 'C'
    else:
        if apologize:
            return 'C'
        last_me = my[-1]
        last_op = op[-1]
        if last_op == 'D':
            if last_me == 'D' and opp_coop_rate > 0.5:
                return 'C'
            return 'D'
        return 'C'
